local UIFeelingShopAscensionDialog = Class("UIFeelingShopAscensionDialog")

function UIFeelingShopAscensionDialog:__init() 
    self._catId = nil              --角色id
    self._catVo = nil
    self._oldLevel = nil           --原等级
    self._newLevel = nil           --现等级
end

function UIFeelingShopAscensionDialog:__delete()
    self._catId = nil              --角色id
    self._catVo = nil
    self._oldLevel = nil           --原等级
    self._newLevel = nil           --现等级
end

function UIFeelingShopAscensionDialog:Awake()
    local argument = self.controller.Argument.parameters
    if not argument then
        return
    end
    self._isShopUp = checkNumber(argument.isShopUp)
    self._catId = checkNumber(argument.catId)  --
    self._catVo = PhoneUtils.GetCatVo(self._catId)
    if  not self._catVo then 
        return
    end
    self._oldLevel = checkNumber(argument.oldLevel)  --
    self._newLevel = checkNumber(argument.newLevel)  --

    self:FillSelf()
    self:FillRewards()
end

function UIFeelingShopAscensionDialog:FillSelf()
    CfUtils.FillText(self.Txtascension, localize("好感提升"))
    CfUtils.FillText(self.Txtclose, localize("点击空白处关闭"))
    local skinCardId = PhoneUtils.GetRoleCurCardSkinId(self._catId)
    CfUtils.FillImage(self.ImgRole, CardConfMgr:GetInstance():GetCardDefaultBodyIconPath(skinCardId), false)
    CfUtils.FillText(self.OldLevel, self._oldLevel)
    CfUtils.FillText(self.NewLevel, self._newLevel)
    CfUtils.FillText(self.TxtCatNameEng, self._catVo.englishName)
    CfUtils.FillText(self.TxtCatName, PhoneUtils.GetRoleCurName(self._catId))

    self:FillRewards()
end

function UIFeelingShopAscensionDialog:FillRewards()
    --大于10级暂时没奖励
    if checkNumber(self._newLevel) > 10 then
        KTool.SetActive(self.Txtunlock, false)
        KTool.SetActive(self.Imglock, false)
        return
    end
    
    local rewards = PhoneUtils.GetLikabilityRewardDatas(self._catId, self._newLevel)

    if not rewards then
        KTool.SetActive(self.Txtunlock, false)
        KTool.SetActive(self.Imglock, false)
        return
    end
    if checkNumber(rewards.quest) ~= 0 then
        KTool.SetActive(self.UnlockPhone, true)
        CfUtils.FillText(self.Txtunlock, localize("角色剧情解锁"))

        local questVo = QuestConfMgr:GetInstance():GetQuestVoById(rewards.quest)
        if questVo then
            local vo = QuestConfMgr:GetInstance():GetRoleStoryChapterVo(questVo.stageID)
            if vo then
                CfUtils.FillText(self.TxtName, vo.name)
            end
        end
    elseif table.count(rewards.items) > 0 then
        CfUtils.FillText(self.Txtunlock, localize("物品解锁"))
        if rewards.items then
            for k, v in pairs(rewards.items) do
                if not self._itemLoader then
                    self._itemLoader = CS.Engine.Modules.ResourceModule.LoadBundleSync("Prefabs/Common/GoodNode.prefab", nil, true)
                end
                if self._itemLoader.IsSuccess then
                    local go = self.Items.transform:Find("item"..k)
                    if not go then 
                        go = CfUtils.InstantiateGo(self._itemLoader.ResultObject, self.Items)
                        go.name = "item"..k
                    end
                    if go then
                        CfUtils.RefeshGoodGo(go, v.goodsId, nil, 0.7)
                    end
                end
            end
        end
    else
        KTool.SetActive(self.Txtunlock, false)
        KTool.SetActive(self.Imglock, false)
    end
end

function UIFeelingShopAscensionDialog:FillReward()

end

function UIFeelingShopAscensionDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        SetButtonAction(self.BG, function()
            --UIModule.CloseDialog(self.controller)
            if checkNumber(self._isShopUp) == 1 then
                cs_coroutine.start(function()
                    cs_coroutine.yield_return(UIModule.BackDialog())
                    UIModule.BackDialog()
                end)
            else
                UIModule.CloseDialog(self.controller)
            end
        end)
        CfUtils.SetTopCommonActive(false, false)
        CfUtils.SetUICameraProjection(true)
    end))
    return coWait
end

function UIFeelingShopAscensionDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if not isNull(self._itemLoader) then
            self._itemLoader:Release()
            self._itemLoader = nil
        end
        CfUtils.SetTopCommonActive(true, false)
        CfUtils.SetUICameraProjection(false)
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIFeelingShopAscensionDialog
